    const auto& BMI_range = BMI_std.at(sex);
    if (BMI > BMI_range[1]) {

        return 1;
    }
    else if (BMI < BMI_range[0]) {

        return -1;
    }
    else {

        return 0;
    }
}

double FitnessTracker::calculate_calorie_intake() const {
    double BMR;
    if (sex == "male") {
        BMR = 10 * weight + 6.25 * height - 5 * age + 5;
    }
    else {
        BMR = 10 * weight + 6.25 * height - 5 * age - 161;
    }

