                        double z00 = z[i][j];
                        double z01 = z[i][j + 1];
                        double z10 = z[i + 1][j];
                        double z11 = z[i + 1][j + 1];
                        double zi = (z00 * (x[i + 1] - xi) * (y[j + 1] - yi) +
                            z10 * (xi - x[i]) * (y[j + 1] - yi) +
