    }

    std::vector<std::vector<std::string>> results;
    int result = sqlite3_step(stmt);
    while (result == SQLITE_ROW) {
        std::vector<std::string> row;
        for (int i = 0; i < sqlite3_column_count(stmt); ++i) {
