        self.doc = ET.ElementTree()

    def read_xml(self):
        try:
            self.doc = ET.parse(self.file_name)
        except (ET.ParseError, OSError):
            # LoadFile clears the document before loading, so on failure it is empty.
            self.doc = ET.ElementTree()
