    x = x / 180.0 * PI; 
    int sign = 1; 

    for (int k = 0; k < n; ++k) {
        double term = std::pow(x, 2 * k) / factorial(2 * k);
        if (k % 2 == 0) {
            a += term;
        }
        else {
            a -= term;
        }
    }
    return a;
}

