#include <map>
#include <sstream>
#include <stdexcept>
#include <string>

using Map = std::map<std::string, std::any>;

class AccessGatewayFilter {
public:
    AccessGatewayFilter() = default;

    bool filter(Map& request) {
        std::string& requestUri = std::any_cast<std::string&>(request.at("path"));

