        direction = -1;
        row = 0;
        col = 0;

        for (std::size_t i = 0; i < len; i++) {
            if (row == 0 || row == rails - 1) {
                direction = -direction;
            }
            plainText.push_back(fence.at(row).at(col++));
            row += direction;
        }

        return plainText;
    }
