                    operatorStack.pop_back();
                }
                operatorStack.push_back(ch);
            }
        }
        while (!operatorStack.empty()) {
            postfixStack.push_back(std::string(1, operatorStack.back()));
            operatorStack.pop_back();
        }
    }

