static std::vector<std::string> splitWhitespace(const std::string& s) {
    std::vector<std::string> tokens;
    std::string cur;
    bool leading = false;
    // Java split("\\s+"): if starts with whitespace, first token is ""
    size_t i = 0;
    if (i < s.size() && isspace(static_cast<unsigned char>(s[i]))) {
