Full implementation:

```cpp
static std::vector<std::string> splitOnWhitespace(const std::string& s) {
    auto isWs = [](unsigned char c) {
        return c == ' ' || c == '\t' || c == '\n' || c == '\x0B' || c == '\f' || c == '\r';
    };
    std::vector<std::string> tokens;
    std::string cur;
    bool matched = false;
    size_t i = 0;
    if (!s.empty() && isWs((unsigned char)s[0])) {
        tokens.push_back("");
        matched = true;
        while (i < s.size() && isWs((unsigned char)s[i])) i++;
    }
    while (i < s.size()) {
        if (isWs((unsigned char)s[i])) {
            tokens.push_back(cur);
            cur.clear();
            while (i < s.size() && isWs((unsigned char)s[i])) i++;
        } else {
            cur += s[i++];
        }
    }
    if (!matched) {
        return {s};
    }
    tokens.push_back(cur);
    while (!tokens.empty() && tokens.back().empty()) tokens.pop_back();
    return tokens;
}
```

