// Java's InetAddress.getByName/getCanonicalHostName semantics are mirrored with
// getaddrinfo/getnameinfo (POSIX name resolution, incl. hostnames and IP literals).

#include <cstring>
#include <memory>
#include <optional>
#include <string>

#ifdef _WIN32
#  include <winsock2.h>
#  include <ws2tcpip.h>
