```cpp
std::string parseString() {
    expect('"');
    std::string out;
    while (true) {
        if (pos_ >= text_.size()) throw JsonParseError("unterminated string");
        char c = text_[pos_++];
        if (c == '"') return out;
        if (c == '\\') {
            if (pos_ >= text_.size()) throw JsonParseError("bad escape");
            char e = text_[pos_++];
            switch (e) {
                case '"': out += '"'; break;
                case '\\': out += '\\'; break;
                case '/': out += '/'; break;
                case 'b': out += '\b'; break;
                case 'f': out += '\f'; break;
                case 'n': out += '\n'; break;
                case 'r': out += '\r'; break;
                case 't': out += '\t'; break;
                case 'u': {
                    if (pos_ + 4 > text_.size()) throw JsonParseError("bad unicode escape");
                    unsigned v = 0;
                    for (int k = 0; k < 4; ++k) {
                        char h = text_[pos_++];
                        v <<= 4;
                        if (h >= '0' && h <= '9') v |= (h - '0');
                        else if (h >= 'a' && h <= 'f') v |= (h - 'a' + 10);
                        else if (h >= 'A' && h <= 'F') v |= (h - 'A' + 10);
                        else throw JsonParseError("bad unicode escape");
                    }
                    // encode UTF-8
                    if (v < 0x80) out += static_cast<char>(v);
                    else if (v < 0x800) {
                        out += static_cast<char>(0xC0 | (v >> 6));
                        out += static_cast<char>(0x80 | (v & 0x3F));
                    } else {
                        out += static_cast<char>(0xE0 | (v >> 12));
                        out += static_cast<char>(0x80 | ((v >> 6) & 0x3F));
                        out += static_cast<char>(0x80 | (v & 0x3F));
                    }
                    break;
                }
                default: throw JsonParseError("bad escape");
            }
        } else {
            out += c;
        }
    }
}
```

