        if (c == '{') { skipObject(); return; }
        if (c == '[') { skipArray(); return; }
        if (c == 't') { expectWord("true"); return; }
        if (c == 'f') { expectWord("false"); return; }
        if (c == 'n') { expectWord("null"); return; }
        if (c == '-' || (c >= '0' && c <= '9')) { skipNumber(); return; }
        throw JsonParseException("unexpected character");
    }

    std::string parseString() {
        expect('"');
        std::string out;
        while (true) {
            char c = nextChar();
            if (c == '"') return out;
            if (c == '\\') {
                char e = nextChar();
                switch (e) {
                    case '"':  out += '"';  break;
                    case '\\': out += '\\'; break;
                    case '/':  out += '/';  break;
                    case 'b':  out += '\b'; break;
                    case 'f':  out += '\f'; break;
                    case 'n':  out += '\n'; break;
                    case 'r':  out += '\r'; break;
                    case 't':  out += '\t'; break;
                    case 'u': {
                        unsigned v = 0;
                        for (int k = 0; k < 4; ++k) {
                            char h = nextChar();
                            v <<= 4;
                            if (h >= '0' && h <= '9')      v |= static_cast<unsigned>(h - '0');
                            else if (h >= 'a' && h <= 'f') v |= static_cast<unsigned>(h - 'a' + 10);
                            else if (h >= 'A' && h <= 'F') v |= static_cast<unsigned>(h - 'A' + 10);
