        }
        std::ostringstream buffer;
        buffer << reader.rdbuf();
        try {
            return JsonParser(buffer.str()).parseDocument();
        } catch (const JsonParseException&) {
            return CookiesMap();  // ParseException path
        }
        // JsonCastException propagates, like the uncaught ClassCastException.
    }

