        std::string cookiesString;
        if (cookies != nullptr) {
            for (CookiesMap::const_iterator it = cookies->begin(); it != cookies->end(); ++it) {
                if (!cookiesString.empty()) {
                    cookiesString += "; ";
                }
                cookiesString += it->first;
                cookiesString += "=";
                cookiesString += it->second;
            }
        }
        request["cookies"] = cookiesString;
    }

