        while (!parts.empty() && parts.back().empty()) parts.pop_back();
        return parts;
    }

    static void appendWhere(std::string& query, const LinkedHashMap* where) {
        if (where != nullptr && !where->isEmpty()) {
            query += " WHERE ";
            bool first = true;
            for (const LinkedHashMap::Entry& entry : where->entrySet()) {
                if (!first) query += " AND ";
                query += entry.first;
                query += "='";
                query += entry.second;
                query += "'";
                first = false;
            }
        }
    }

