// Parser equivalent to Python's csv.reader with default dialect
// (comma delimiter, '"' quote char, doubled quotes, records end with \n, \r or \r\n).
inline std::vector<std::vector<std::string>> parse(const std::string& content) {
    std::vector<std::vector<std::string>> rows;
    std::vector<std::string> row;
    std::string field;
    bool in_quotes = false;
    bool started = false;  // any character/field seen in the current record

    size_t i = 0;
    const size_t n = content.size();
    while (i < n) {
        char c = content[i];
        if (in_quotes) {
            if (c == '"') {
                if (i + 1 < n && content[i + 1] == '"') { field += '"'; i += 2; }
                else { in_quotes = false; ++i; }
            } else { field += c; ++i; }
        } else if (c == '"') {
            in_quotes = true; started = true; ++i;
        } else if (c == ',') {
            row.push_back(field); field.clear(); started = true; ++i;
        } else if (c == '\n' || c == '\r') {
            i += (c == '\r' && i + 1 < n && content[i + 1] == '\n') ? 2 : 1;
