            else { row.push_back(field); field.clear(); rows.push_back(row); row.clear(); }
            started = false;
        } else {
            field += c; started = true; ++i;
        }
    }
    if (in_quotes || started) {  // unterminated final record
        row.push_back(field);
        rows.push_back(row);
    }
