            BMR = 10 * weight + 6.25 * height - 5 * age + 5;
        } else {
            BMR = 10 * weight + 6.25 * height - 5 * age - 161;
        }
        double calorie_intake;
        if (condition_judge() == 1) {
            calorie_intake = BMR * 1.2;  // Sedentary lifestyle
