            calorie_intake = BMR * 1.6;  // Active lifestyle
        } else {
            calorie_intake = BMR * 1.4;  // Moderate lifestyle
        }
        return calorie_intake;
    }

private:
    double height;
    double weight;
    int age;
    std::string sex;
    std::vector<std::pair<std::string, std::pair<double, double>>> BMI_std;
};
