#include <algorithm>
#include <cctype>
#include <optional>
#include <string>
#include <utility>
#include <variant>
#include <vector>
#include <xlnt/xlnt.hpp>

class ExcelProcessor {
public:
    ExcelProcessor() = default;

    // Reading data from Excel files.
    // Returns the rows of the active sheet, or std::nullopt on any failure
    // (Python: returns None on any exception).
    std::optional<std::vector<std::vector<std::string>>> read_excel(const std::string& file_name) const {
        std::vector<std::vector<std::string>> data;
        try {
            xlnt::workbook workbook;
            workbook.load(file_name);
            xlnt::worksheet sheet = workbook.active_sheet();
            for (const auto& row : sheet.rows(false)) {
                std::vector<std::string> cells;
                cells.reserve(row.length());
                for (const auto& cell : row)
                    cells.push_back(cell.to_string());
                data.push_back(std::move(cells));
            }
            return data;
        } catch (...) {
            return std::nullopt;
        }
    }

    // Write data to the specified Excel file.
    // Returns 1 on success, 0 on failure.
    int write_excel(const std::vector<std::vector<std::string>>& data, const std::string& file_name) const {
        try {
            xlnt::workbook workbook;
            xlnt::worksheet sheet = workbook.active_sheet();
            for (const auto& row : data)
                sheet.append(row);
            workbook.save(file_name);
            return 1;
        } catch (...) {
            return 0;
        }
    }

    // Change the specified column ... returns write_excel's return value and the
    // new file name; on failure returns just 0 (Python returns the int 0 alone).
    std::variant<int, std::pair<int, std::string>>
    process_excel_data(std::size_t N, const std::string& save_file_name) const {
        auto data = read_excel(save_file_name);
        if (!data.has_value() || N >= data->at(0).size())
            return 0;

        std::vector<std::vector<std::string>> new_data;
        new_data.reserve(data->size());
        for (const auto& row : *data) {
            std::vector<std::string> new_row(row);
            const std::string& value = row.at(N);
            if (!is_digit_str(value))
                new_row.push_back(to_upper(value));
            else
                new_row.push_back(value);
            new_data.push_back(std::move(new_row));
        }

        std::string new_file_name = base_name(save_file_name) + "_process.xlsx";
        int success = write_excel(new_data, new_file_name);
        return std::make_pair(success, new_file_name);
    }

private:
    static bool is_digit_str(const std::string& s) {
        if (s.empty()) return false;
        return std::all_of(s.begin(), s.end(),
                           [](unsigned char c) { return std::isdigit(c); });
    }

    static std::string to_upper(std::string s) {
        std::transform(s.begin(), s.end(), s.begin(),
                       [](unsigned char c) { return static_cast<char>(std::toupper(c)); });
        return s;
    }

    // Equivalent of save_file_name.split('.')[0]
    static std::string base_name(const std::string& name) {
        std::string::size_type pos = name.find('.');
        return pos == std::string::npos ? name : name.substr(0, pos);
    }
};
