```cpp
#include <string>
#include <vector>
#include <cstdint>

class IPAddress {
public:
    explicit IPAddress(const std::string& ip_address) : ip_address(ip_address) {}

    bool is_valid() const {
        std::vector<std::string> octets = split(ip_address, '.');
        if (octets.size() != 4) {
            return false;
        }
        for (const std::string& octet : octets) {
            if (octet.empty() || octet.size() > 3) {
                return false;
            }
            int value = 0;
            for (char c : octet) {
                if (c < '0' || c > '9') {
                    return false;
                }
                value = value * 10 + (c - '0');
            }
            if (value < 0 || value > 255) {
                return false;
            }
        }
        return true;
    }

    std::vector<std::string> get_octets() const {
        if (is_valid()) {
            return split(ip_address, '.');
        }
        return {};
    }

    std::string get_binary() const {
        if (is_valid()) {
            std::string result;
            std::vector<std::string> octets = get_octets();
            for (size_t i = 0; i < octets.size(); ++i) {
                if (i > 0) {
                    result += '.';
                }
                result += to_binary_octet(std::stoi(octets[i]));
            }
            return result;
        }
        return "";
    }

private:
    std::string ip_address;

    static std::vector<std::string> split(const std::string& s, char delimiter) {
        std::vector<std::string> tokens;
        std::string current;
        for (char c : s) {
            if (c == delimiter) {
                tokens.push_back(current);
                current.clear();
            } else {
                current += c;
            }
        }
        tokens.push_back(current);
        return tokens;
    }

    static std::string to_binary_octet(int value) {
        std::string bits(8, '0');
        for (int i = 7; i >= 0; --i) {
            bits[i] = '0' + (value & 1);
            value >>= 1;
        }
        return bits;
    }
};
```

