#include <string>
#include <vector>

class SplitSentence {
public:
    // Split a string into a list of sentences. Sentences end with . or ? and with
    // a space after that. Note that "Mr." also ends with . but is not a sentence.
    std::vector<std::string> split_sentences(const std::string& sentences_string) const {
        std::vector<std::string> sentences;
        std::size_t start = 0;
        for (std::size_t i = 0; i < sentences_string.size(); ++i) {
            if (!is_space(sentences_string[i]))
                continue;
            if (i == 0)
                continue; // (?<=\.|\?) needs a preceding char
            char prev = sentences_string[i - 1];
            if (prev != '.' && prev != '?')
                continue;
            // (?<!\w\.\w.) : 4 chars before must not match \w . \w .
            if (i >= 4) {
                char a = sentences_string[i - 4], b = sentences_string[i - 3];
                char c = sentences_string[i - 2];
                if (is_word(a) && b == '.' && is_word(c) && prev != '\n')
                    continue;
            }
            // (?<![A-Z][a-z]\.) : 3 chars before must not match [A-Z][a-z]\.
            if (i >= 3) {
                char a = sentences_string[i - 3], b = sentences_string[i - 2];
                if (a >= 'A' && a <= 'Z' && b >= 'a' && b <= 'z' && prev == '.')
                    continue;
            }
            sentences.push_back(sentences_string.substr(start, i - start));
            start = i + 1;
        }
        sentences.push_back(sentences_string.substr(start));
        return sentences;
    }

    // Count the number of words in a sentence. Words are separated by spaces;
    // punctuation marks and numbers are not counted as words.
    int count_words(const std::string& sentence) const {
        std::string cleaned;
        for (char c : sentence) {
            if (is_letter(c) || is_space(c))
                cleaned.push_back(c);
        }
        int count = 0;
        bool in_word = false;
        for (char c : cleaned) {
            if (is_space(c)) {
                in_word = false;
            } else if (!in_word) {
                ++count;
                in_word = true;
            }
        }
        return count;
    }

    // Return the number of words in the longest sentence.
    int process_text_file(const std::string& sentences_string) const {
        std::vector<std::string> sentences = split_sentences(sentences_string);
        int max_count = 0;
        for (const std::string& sentence : sentences) {
            int count = count_words(sentence);
            if (count > max_count)
