class TwentyFourPointGame {
public:
    TwentyFourPointGame() : nums() {
        std::random_device rd;
        rng.seed(rd());
    }

    // Generate random numbers between 1 and 9 for the cards.
    void _generate_cards() {
        for (int i = 0; i < 4; ++i) {
            std::uniform_int_distribution<int> dist(1, 9);
            nums.push_back(dist(rng));
        }
        assert(nums.size() == 4);
    }

    // Get a list of four random numbers between 1 and 9 representing the player's cards.
    std::vector<int> get_my_cards() {
        nums.clear();
        _generate_cards();
        return nums;
    }

    std::variant<bool, std::vector<int>> answer(const std::string& expression) {
        if (expression == "pass") {
            return get_my_cards();
        }
        std::map<std::string, int> statistic;
        for (char c : expression) {
            if (std::isdigit(static_cast<unsigned char>(c))) {
                int d = c - '0';
                if (contains(nums, d)) {
                    std::string key(1, c);
                    statistic[key] += 1;
                }
            }
        }

        std::map<std::string, int> nums_used = statistic;

        for (int num : nums) {
            std::string key = std::to_string(num);
            auto it = nums_used.find(key);
            if (it != nums_used.end() && it->second > 0) {
                it->second -= 1;
            } else {
                return false;
            }
        }

        bool all_zero = true;
        for (const auto& kv : nums_used) {
            if (kv.second != 0) { all_zero = false; break; }
        }
        if (all_zero) {
            return evaluate_expression(expression);
        } else {
            return false;
        }
    }

    // Evaluate a mathematical expression and check if the result is 24.
    bool evaluate_expression(const std::string& expression) {
        try {
            double result = Parser(expression).parse();
            return result == 24.0;
        } catch (...) {
            return false;
        }
    }

    std::vector<int> nums;

private:
    std::mt19937 rng;

    static bool contains(const std::vector<int>& v, int x) {
        for (int e : v) if (e == x) return true;
        return false;
    }

    // Small recursive-descent evaluator for arithmetic expressions
    // (numbers, + - * /, parentheses, unary +/-). Mirrors Python eval
    // semantics for the subset used by the 24-game; any parse error
    // throws, which evaluate_expression converts to false.
    struct Parser {
        const std::string& s;
        size_t pos = 0;

        Parser(const std::string& str) : s(str) {}

        void skip_ws() { while (pos < s.size() && std::isspace(static_cast<unsigned char>(s[pos]))) ++pos; }

        double parse() {
            double v = parse_expr();
            skip_ws();
            if (pos != s.size()) throw std::runtime_error("unexpected trailing input");
            return v;
        }

        double parse_expr() {
            double v = parse_term();
            while (true) {
                skip_ws();
                if (pos < s.size() && (s[pos] == '+' || s[pos] == '-')) {
                    char op = s[pos++];
                    double rhs = parse_term();
                    v = (op == '+') ? v + rhs : v - rhs;
                } else break;
            }
            return v;
        }

        double parse_term() {
            double v = parse_factor();
            while (true) {
                skip_ws();
                if (pos < s.size() && (s[pos] == '*' || s[pos] == '/')) {
                    char op = s[pos++];
                    double rhs = parse_factor();
                    v = (op == '*') ? v * rhs : v / rhs;
                } else break;
            }
            return v;
        }

        double parse_factor() {
            skip_ws();
            if (pos < s.size() && (s[pos] == '+' || s[pos] == '-')) {
                char sign = s[pos++];
                double v = parse_factor();
                return (sign == '-') ? -v : v;
            }
            if (pos < s.size() && s[pos] == '(') {
                ++pos;
                double v = parse_expr();
                skip_ws();
                if (pos >= s.size() || s[pos] != ')') throw std::runtime_error("expected ')'");
                ++pos;
                return v;
            }
            return parse_number();
        }

        double parse_number() {
            skip_ws();
            size_t start = pos;
            while (pos < s.size() && (std::isdigit(static_cast<unsigned char>(s[pos])) || s[pos] == '.')) ++pos;
            if (start == pos) throw std::runtime_error("expected number");
            try {
                return std::stod(s.substr(start, pos - start));
            } catch (...) {
                throw std::runtime_error("bad number");
            }
        }
    };
};
