    struct ExprParser {
        const std::string& s;
        std::size_t pos;

        explicit ExprParser(const std::string& str) : s(str), pos(0) {}

        void skip_ws() {
            while (pos < s.size() &&
                   std::isspace(static_cast<unsigned char>(s[pos]))) {
                ++pos;
            }
        }

        double parse() {
            double value = expression();
            skip_ws();
            if (pos != s.size()) {
                throw std::runtime_error("unexpected trailing characters");
            }
            return value;
        }

        double expression() {
            double value = term();
            while (true) {
                skip_ws();
                if (pos < s.size() && (s[pos] == '+' || s[pos] == '-')) {
                    char op = s[pos++];
                    double rhs = term();
                    value = (op == '+') ? value + rhs : value - rhs;
                } else {
                    break;
                }
            }
            return value;
        }

        double term() {
            double value = factor();
            while (true) {
                skip_ws();
                if (pos < s.size() && (s[pos] == '*' || s[pos] == '/')) {
                    char op = s[pos++];
                    double rhs = factor();
                    value = (op == '*') ? value * rhs : value / rhs;
                } else {
                    break;
                }
            }
            return value;
        }

        double factor() {
            skip_ws();
            if (pos < s.size() && (s[pos] == '+' || s[pos] == '-')) {
                char sign = s[pos++];
                double value = factor();
                return (sign == '-') ? -value : value;
            }
            if (pos < s.size() && s[pos] == '(') {
                ++pos;
                double value = expression();
                skip_ws();
                if (pos >= s.size() || s[pos] != ')') {
                    throw std::runtime_error("expected ')'");
                }
                ++pos;
                return value;
            }
            return number();
        }

        double number() {
            skip_ws();
            std::size_t start = pos;
            while (pos < s.size() &&
                   (std::isdigit(static_cast<unsigned char>(s[pos])) ||
                    s[pos] == '.')) {
                ++pos;
            }
            if (start == pos) {
                throw std::runtime_error("expected a number");
            }
            return std::stod(s.substr(start, pos - start));
        }
    };
