class TimeUtils {
public:
    // Naive (field-based) local datetime captured at construction, like datetime.datetime.now()
    std::tm datetime;

    TimeUtils()
    {
        const std::time_t now = std::time(nullptr);
        datetime = *std::localtime(&now);
